insert into stores(name,slug) values ('Amazon','amazon'),('Flipkart','flipkart'),('Nykaa','nykaa'),('Myntra','myntra');
insert into categories(name,slug,display_order) values ('Electronics','electronics',1),('Beauty','beauty',2),('Fashion','fashion',3);
insert into price_ranges(label,min_price,max_price,display_order) values ('Under ₹1,000',0,1000,1),('Under ₹2,000',1001,2000,2);
insert into products(slug,name,description,store_id,outbound_url,current_price,original_price,status,expires_at) select 'wireless-headphones','Wireless Headphones','Comfortable over-ear headphones with rich sound and all-day battery.',id,'https://www.amazon.in/',1299,2499,'ACTIVE',now()+interval '30 days' from stores where slug='amazon';
insert into products(slug,name,description,store_id,outbound_url,current_price,original_price,status) select 'everyday-smartwatch','Everyday Smartwatch','A clean, simple smartwatch for everyday movement.',id,'https://www.flipkart.com/',1799,2999,'ACTIVE' from stores where slug='flipkart';
insert into products(slug,name,description,store_id,outbound_url,current_price,status) select 'daily-care-set','Daily Care Set','An uncomplicated personal-care essential set.',id,'https://www.nykaa.com/',699,'ACTIVE' from stores where slug='nykaa';
insert into products(slug,name,description,store_id,outbound_url,current_price,status) select 'canvas-tote','Canvas Tote','A durable tote made for the day-to-day.',id,'https://www.myntra.com/',899,'ACTIVE' from stores where slug='myntra';
insert into product_categories(product_id,category_id) select p.id,c.id from products p join categories c on (p.slug in ('wireless-headphones','everyday-smartwatch') and c.slug='electronics') or (p.slug='daily-care-set' and c.slug='beauty') or (p.slug='canvas-tote' and c.slug='fashion');
insert into explore_products(product_id,display_order) select id,row_number() over(order by name) from products;
insert into best_item_placements(product_id,category_id,price_range_id,rank) select p.id,c.id,r.id,case p.slug when 'wireless-headphones' then 1 else 2 end from products p join categories c on c.slug='electronics' join price_ranges r on r.label='Under ₹2,000' where p.slug in ('wireless-headphones','everyday-smartwatch');
